-- 098: 科研文档共享、科研服务催办及统一消息通道。
-- 文档版本、授权、下载和撤销均留痕；短信/邮件/微信/企业微信只登记配置和队列，
-- 没有真实适配器回执时不得写入“已发送”。所有通道默认停用。
BEGIN;

CREATE TABLE IF NOT EXISTS "科研文档" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "文档编码" varchar(100) NOT NULL,
    "文档名称" varchar(300) NOT NULL,
    "文档分类" varchar(100) NOT NULL DEFAULT '未分类',
    "文档说明" text,
    "授权模式" varchar(20) NOT NULL DEFAULT '按授权',
    "是否启用" boolean NOT NULL DEFAULT TRUE,
    "创建人编号" integer REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_科研文档_编码" UNIQUE ("文档编码"),
    CONSTRAINT "ck_科研文档_授权模式" CHECK ("授权模式" IN ('公开','按授权'))
);

CREATE TABLE IF NOT EXISTS "科研文档版本" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "文档编号" bigint NOT NULL REFERENCES "科研文档"("编号") ON DELETE CASCADE,
    "版本号" varchar(50) NOT NULL,
    "文件名称" varchar(500) NOT NULL,
    "文件路径" varchar(2000) NOT NULL,
    "文件大小" bigint,
    "SHA256" char(64),
    "版本状态" varchar(20) NOT NULL DEFAULT '草稿',
    "上传人编号" integer REFERENCES "人员"("编号"),
    "发布日期" timestamp without time zone,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_科研文档版本_文档版本" UNIQUE ("文档编号", "版本号"),
    CONSTRAINT "ck_科研文档版本_状态" CHECK ("版本状态" IN ('草稿','生效','撤销')),
    CONSTRAINT "ck_科研文档版本_大小" CHECK ("文件大小" IS NULL OR "文件大小" >= 0),
    CONSTRAINT "ck_科研文档版本_sha" CHECK ("SHA256" IS NULL OR "SHA256" ~ '^[0-9A-Fa-f]{64}$')
);

CREATE UNIQUE INDEX IF NOT EXISTS "uq_科研文档版本_当前生效"
    ON "科研文档版本" ("文档编号") WHERE "版本状态" = '生效';
CREATE INDEX IF NOT EXISTS "ix_科研文档版本_文档状态"
    ON "科研文档版本" ("文档编号", "版本状态", "创建时间" DESC);

CREATE TABLE IF NOT EXISTS "科研文档授权" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "文档编号" bigint NOT NULL REFERENCES "科研文档"("编号") ON DELETE CASCADE,
    "授权类型" varchar(20) NOT NULL,
    "授权对象编号" integer NOT NULL DEFAULT 0,
    "可下载" boolean NOT NULL DEFAULT TRUE,
    "有效开始" timestamp without time zone,
    "有效结束" timestamp without time zone,
    "是否撤销" boolean NOT NULL DEFAULT FALSE,
    "撤销时间" timestamp without time zone,
    "授权人编号" integer REFERENCES "人员"("编号"),
    "授权时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_科研文档授权_对象" UNIQUE ("文档编号", "授权类型", "授权对象编号"),
    CONSTRAINT "ck_科研文档授权_类型" CHECK ("授权类型" IN ('所有人','人员','部门','角色')),
    CONSTRAINT "ck_科研文档授权_对象" CHECK (("授权类型" = '所有人' AND "授权对象编号" = 0) OR ("授权类型" <> '所有人' AND "授权对象编号" > 0)),
    CONSTRAINT "ck_科研文档授权_期限" CHECK ("有效结束" IS NULL OR "有效开始" IS NULL OR "有效结束" >= "有效开始")
);
CREATE INDEX IF NOT EXISTS "ix_科研文档授权_对象"
    ON "科研文档授权" ("授权类型", "授权对象编号", "是否撤销");

CREATE TABLE IF NOT EXISTS "科研文档下载日志" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "文档编号" bigint NOT NULL REFERENCES "科研文档"("编号") ON DELETE CASCADE,
    "版本编号" bigint REFERENCES "科研文档版本"("编号"),
    "下载人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "下载结果" varchar(20) NOT NULL DEFAULT '允许',
    "客户端IP" varchar(64),
    "用户代理" varchar(500),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_科研文档下载_结果" CHECK ("下载结果" IN ('允许','拒绝','文件不存在'))
);
CREATE INDEX IF NOT EXISTS "ix_科研文档下载_文档时间"
    ON "科研文档下载日志" ("文档编号", "创建时间" DESC);

ALTER TABLE "科研导入导出日志"
    ADD COLUMN IF NOT EXISTS "撤销原因" varchar(1000),
    ADD COLUMN IF NOT EXISTS "撤销人编号" integer REFERENCES "人员"("编号");

CREATE TABLE IF NOT EXISTS "科研服务催办日志" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "服务申请编号" bigint NOT NULL REFERENCES "科研服务申请"("编号") ON DELETE CASCADE,
    "催办人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "接收人编号" integer REFERENCES "人员"("编号"),
    "催办原因" varchar(1000),
    "消息队列编号" bigint,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "ix_科研服务催办_申请时间"
    ON "科研服务催办日志" ("服务申请编号", "创建时间" DESC);

CREATE TABLE IF NOT EXISTS "消息通道" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "通道类型" varchar(20) NOT NULL,
    "通道名称" varchar(200) NOT NULL,
    "服务地址" varchar(1000),
    "凭据引用" varchar(300),
    "配置JSON" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "通道状态" varchar(20) NOT NULL DEFAULT '待配置',
    "是否启用" boolean NOT NULL DEFAULT FALSE,
    "最后测试时间" timestamp without time zone,
    "最后测试状态" varchar(20) NOT NULL DEFAULT '未执行',
    "最后测试提示" varchar(1000),
    "创建人编号" integer REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_消息通道_名称" UNIQUE ("通道名称"),
    CONSTRAINT "ck_消息通道_类型" CHECK ("通道类型" IN ('短信','邮件','微信','企业微信')),
    CONSTRAINT "ck_消息通道_状态" CHECK ("通道状态" IN ('待配置','待验证','已验证','验证失败','已停用')),
    CONSTRAINT "ck_消息通道_启用条件" CHECK (NOT "是否启用" OR "通道状态" = '已验证')
);

CREATE TABLE IF NOT EXISTS "消息模板" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "模板编码" varchar(100) NOT NULL,
    "模板名称" varchar(200) NOT NULL,
    "消息类型" varchar(50) NOT NULL DEFAULT '待办提醒',
    "标题模板" varchar(500) NOT NULL,
    "正文模板" text NOT NULL,
    "变量定义" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "是否启用" boolean NOT NULL DEFAULT TRUE,
    "创建人编号" integer REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_消息模板_编码" UNIQUE ("模板编码")
);

CREATE TABLE IF NOT EXISTS "消息发送队列" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "通道编号" bigint REFERENCES "消息通道"("编号"),
    "模板编号" bigint REFERENCES "消息模板"("编号"),
    "消息类型" varchar(50) NOT NULL,
    "业务模块" varchar(100),
    "业务编号" varchar(100),
    "接收人编号" integer REFERENCES "人员"("编号"),
    "接收地址" varchar(300),
    "消息标题" varchar(500) NOT NULL,
    "消息正文" text,
    "请求载荷" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "队列状态" varchar(20) NOT NULL DEFAULT '待发送',
    "重试次数" integer NOT NULL DEFAULT 0,
    "最大重试次数" integer NOT NULL DEFAULT 3,
    "下次重试时间" timestamp without time zone,
    "外部消息编号" varchar(200),
    "真实回执时间" timestamp without time zone,
    "最后错误" varchar(1000),
    "创建人编号" integer REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_消息队列_状态" CHECK ("队列状态" IN ('待发送','发送中','已发送','发送失败','未配置','已取消')),
    CONSTRAINT "ck_消息队列_重试" CHECK ("重试次数" >= 0 AND "最大重试次数" BETWEEN 0 AND 20)
);
CREATE INDEX IF NOT EXISTS "ix_消息队列_待处理"
    ON "消息发送队列" ("队列状态", "下次重试时间", "创建时间");
CREATE INDEX IF NOT EXISTS "ix_消息队列_接收人"
    ON "消息发送队列" ("接收人编号", "创建时间" DESC);

CREATE TABLE IF NOT EXISTS "消息发送尝试" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "队列编号" bigint NOT NULL REFERENCES "消息发送队列"("编号") ON DELETE CASCADE,
    "尝试序号" integer NOT NULL,
    "尝试状态" varchar(20) NOT NULL,
    "响应摘要" varchar(1000),
    "外部消息编号" varchar(200),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_消息尝试_序号" UNIQUE ("队列编号", "尝试序号"),
    CONSTRAINT "ck_消息尝试_状态" CHECK ("尝试状态" IN ('排队','成功','失败','未配置'))
);

INSERT INTO "权限" ("编号", "上级编号", "名称", "路径", "类型", "备注")
VALUES (210, 2, '科研文档共享与消息中心', '科研办公/科研办公/科研文档共享与消息中心.html', TRUE,
        '科研文档分类、版本、授权下载、服务催办和短信邮件微信消息队列')
ON CONFLICT ("编号") DO UPDATE SET "名称"=EXCLUDED."名称", "路径"=EXCLUDED."路径", "备注"=EXCLUDED."备注";
INSERT INTO "角色权限" ("角色编号", "权限编号")
SELECT r."编号", 210 FROM "角色" r
WHERE r."名称" IN ('系统管理员','科研管理员','科技办')
  AND NOT EXISTS (SELECT 1 FROM "角色权限" rp WHERE rp."角色编号"=r."编号" AND rp."权限编号"=210);

UPDATE "系统迁移版本"
SET "版本"=98, "脚本"='098_document_service_messaging.sql',
    "检查摘要"='增加科研文档版本授权下载、服务催办和短信邮件微信企业微信消息队列',
    "应用时间"=CURRENT_TIMESTAMP
WHERE "编号"=1;

COMMIT;
